/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest message whose id has not been finalized; ack finalizes a
 * message; failed messages are put back on the queue for a later retry.
 *
 * dequeue(now) is retry-aware and order-aware:
 * - an entry whose retryAt is still in the future is not due yet and is left
 *   in place (when `now` is omitted, every entry counts as due);
 * - while such an entry waits, every later entry with the same key waits with
 *   it, so a retrying message can never be overtaken by its own key. Entries
 *   with other keys are unaffected, so one waiting key cannot block the rest.
 *
 * requeue() puts a message back at the HEAD of the queue, keeping it ahead of
 * the messages that were enqueued after it; combined with the per-key wait in
 * dequeue this preserves per-key enqueue order across retries.
 */
export function createQueue() {
  const entries = []
  const done = new Set()
  return {
    enqueue(message) {
      entries.push({ ...message, attempts: message.attempts ?? 0 })
    },
    dequeue(now) {
      const blockedKeys = new Set()
      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i]
        if (done.has(entry.id)) continue
        if (now !== undefined && entry.retryAt !== undefined && entry.retryAt > now) {
          // Not due yet: it stays, and its key waits with it.
          blockedKeys.add(entry.key)
          continue
        }
        if (blockedKeys.has(entry.key)) continue
        return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      entries.unshift(message)
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
  }
}

/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest message whose id has not been finalized; ack finalizes a
 * message; failed messages are put back on the queue for a later retry.
 *
 * dequeue(now) is retry-aware and order-aware:
 * - an entry whose retryAt is still in the future is not due yet and is left
 *   in place (when `now` is omitted, every entry counts as due);
