/**
 * Delivery pump: dequeue → skip duplicates → claim → emit + process → ack, or
 * requeue with backoff on failure.
 *
 * Effectively-once: an id is CLAIMED before the delivery attempt happens —
 * written to the permanent pump-level claim set and to the (windowed) dedup
 * guard — and only then is the attempt recorded in the sink and the downstream
 * called. The claim happens up front because a failed attempt is ambiguous:
 * the downstream may already have accepted the message even though
 * processMessage reported failure, so a retry must never re-attempt it. When a
 * requeued message comes due again, the claim suppresses it: the message is
 * acked, and a retried failure is reported through sink.failed. The claim set
 * has no expiry, so suppression holds under any clock advance — even past the
 * dedup window.
 *
 * Per-key ordering: a failed message is requeued at the head of the queue, and
 * queue.dequeue(now) holds back later entries of the same key until the
 * requeued message resolves, so a retry never lets a later same-key message
 * overtake it. Other keys keep flowing.
 *
 * One clock snapshot (now) is taken per iteration and used for the dequeue
 * due-check, the duplicate check, the dedup record and the backoff schedule,
 * so no clock movement inside an iteration can produce a mixed decision.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const retrier = retryWithBackoff(clock)
  const claimed = new Set()
  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const now = clock.now()
        const message = queue.dequeue(now)
        if (message === null) break
        const retried = message.awaitingRetry === true
        if (claimed.has(message.id) || dedup.isDuplicate(message.id, now)) {
          // Already attempted (or seen within the window): the attempt's
          // outcome is ambiguous, so re-delivering is never allowed.
          queue.ack(message.id)
          if (retried) sink.failed(message)
          continue
        }
        claimed.add(message.id)
        dedup.record(message.id, now)
        sink.emit(message)
        let ok = false
        try {
          ok = processMessage(message)
        } catch {
          ok = false
        }
        if (ok) {
          queue.ack(message.id)
          continue
        }
        message.attempts += 1
        if (message.attempts >= maxAttempts) {
          queue.ack(message.id)
          sink.failed(message)
          continue
        }
        message.retryAt = retrier.scheduleRetry(message.attempts, now)
        message.awaitingRetry = true
        queue.requeue(message)
      }
    },
  }
}

import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink, retryWithBackoff } from './src/index.js'

function makeRig({ windowMs = 100, maxAttempts = 3 } = {}) {
  const queue = createQueue()
  const dedup = createDedup({ windowMs })
  const sink = createSink()
  const state = { t: 0 }
  const clock = { now: () => state.t }
  return { queue, dedup, sink, clock, state, maxAttempts }
}

// 1. Core scenario: downstream accepted but pump reported failure.
{
  const { queue, dedup, sink, clock, state } = makeRig({ windowMs: 100 })
  const downstream = []
  const processMessage = (m) => {
    downstream.push(m.id) // downstream accepted...
    return false // ...but the pump reports failure
  }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run(1)
  assert.deepEqual(downstream, ['m1'])
  state.t = 50
  pump.run(5)
  state.t = 5000 // far past the dedup window
  pump.run(5)
  state.t = 100000
  pump.run(5)
  assert.deepEqual(downstream, ['m1'], 'downstream must receive it exactly once')
  assert.deepEqual(sink.deliveredIds(), ['m1'], 'sink sees it at most once')
  assert.equal(sink.hasDuplicate(), false)
  assert.deepEqual(sink.failedIds(), ['m1'], 'retried failure is reported as failed')
  assert.equal(queue.pending().length, 0, 'message resolved out of the queue')
}

// 2. Clock jumps far beyond the dedup window before the retry comes due.
{
  const { queue, dedup, sink, clock, state } = makeRig({ windowMs: 100 })
  let calls = 0
  const processMessage = () => { calls += 1; return false }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run(1) // attempt at t=0, requeued with retryAt=100
  state.t = 1e9 // window long expired
  pump.run(10)
  assert.equal(calls, 1, 'no re-attempt after any clock advance')
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
}

// 3. Per-key ordering holds across retries.
{
  const { queue, dedup, sink, clock, state } = makeRig()
  let firstCall = true
  const processMessage = () => { const ok = !firstCall; firstCall = false; return ok } // m1's attempt fails
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'], 'm2 must not overtake the retrying m1')
  state.t = 1000
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'], 'per-key order preserved across retries')
  assert.equal(sink.hasDuplicate(), false)
}

// 4. A waiting key does not block other keys.
{
  const { queue, dedup, sink, clock, state } = makeRig()
  const processMessage = (m) => m.id !== 'm1' // only m1 fails
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K2', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K2', payload: 3 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2', 'm3'], 'K2 flows while K1 waits for its retry')
  state.t = 1000
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2', 'm3'])
  assert.equal(queue.pending().length, 0)
}

// 5. Liveness: run() with default steps and a static clock must terminate.
{
  const { queue, dedup, sink, clock } = makeRig()
  const processMessage = () => false
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run() // must return, not spin forever
  assert.deepEqual(sink.deliveredIds(), ['m1'])
}

// 6. maxAttempts=1 abandons immediately with a failed report and no requeue wait.
{
  const { queue, dedup, sink, clock } = makeRig({ maxAttempts: 1 })
  const processMessage = () => false
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.deepEqual(sink.deliveredIds().filter((id) => id === 'm2'), [], 'later same-key message untouched')
}

// 7. Duplicate id re-enqueued after delivery (even past the window) is not re-delivered.
{
  const { queue, dedup, sink, clock, state } = makeRig({ windowMs: 100 })
  const processMessage = () => true
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage })
  pump.run(10)
  state.t = 100000
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 }) // stale duplicate after window expiry
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
}

// 8. Queue-level: requeue keeps a message ahead of its same-key successors.
{
  const { queue } = makeRig()
  queue.enqueue({ id: 'a', key: 'K', payload: 1 })
  queue.enqueue({ id: 'b', key: 'K', payload: 2 })
  queue.enqueue({ id: 'c', key: 'J', payload: 3 })
  const a = queue.dequeue()
  assert.equal(a.id, 'a')
  a.retryAt = 500
  queue.requeue(a)
  assert.deepEqual(queue.pending().map((m) => m.id), ['a', 'b', 'c'])
  assert.equal(queue.dequeue(0), null, 'not-due a holds back same-key b')
  assert.equal(queue.dequeue(500).id, 'a', 'a due again at retryAt')
  assert.equal(queue.dequeue(500).id, 'b')
  assert.equal(queue.dequeue(500).id, 'c')
  // Bare dequeue (no now) keeps legacy semantics: everything is due.
  const q2 = createQueue()
  q2.enqueue({ id: 'x', key: 'K', payload: 1 })
  const x = q2.dequeue()
  x.retryAt = 999
  q2.requeue(x)
  assert.equal(q2.dequeue().id, 'x')
}

// 9. Randomized property test: any failure/retry/clock-advance combination.
{
  const retrier = retryWithBackoff(() => 0)
  for (let seed = 0; seed < 300; seed++) {
    let rng = seed * 2654435761 % 4294967296
    const rand = () => { rng = (rng * 1103515245 + 12345) % 2147483648; return rng / 2147483648 }
    const { queue, dedup, sink, clock, state, maxAttempts } = makeRig({ windowMs: 100, maxAttempts: 1 + Math.floor(rand() * 3) })
    const enqueueOrder = []
    const keyOf = new Map()
    const nMsgs = 1 + Math.floor(rand() * 8)
    const nKeys = 1 + Math.floor(rand() * 3)
    for (let i = 0; i < nMsgs; i++) {
      const id = `m${i}`
      const key = `K${Math.floor(rand() * nKeys)}`
      enqueueOrder.push(id)
      keyOf.set(id, key)
      queue.enqueue({ id, key, payload: i })
    }
    const downstream = []
    const processMessage = (m) => { downstream.push(m.id); return rand() < 0.5 } // half lie about acceptance
    const pump = createPump({ queue, dedup, sink, clock, processMessage, maxAttempts })
    for (let round = 0; round < 200; round++) {
      pump.run(1 + Math.floor(rand() * 6))
      state.t += Math.floor(rand() * 3000) // arbitrary clock advance each round
    }
    // (a) effectively-once at the sink and downstream
    assert.equal(sink.hasDuplicate(), false, `seed ${seed}: sink duplicates`)
    assert.deepEqual(sink.deliveredIds(), [...new Set(sink.deliveredIds())], `seed ${seed}: dup ids in delivered`)
    assert.deepEqual(downstream, [...new Set(downstream)], `seed ${seed}: downstream re-delivered`)
    assert.deepEqual(sink.failedIds(), [...new Set(sink.failedIds())], `seed ${seed}: dup failed reports`)
    // (b) per-key order: delivered subsequence per key equals enqueue order
    for (const key of new Set(keyOf.values())) {
      const deliveredByKey = sink.deliveredIds().filter((id) => keyOf.get(id) === key)
      const enqueuedByKey = enqueueOrder.filter((id) => keyOf.get(id) === key)
      assert.deepEqual(deliveredByKey, enqueuedByKey, `seed ${seed}: key ${key} out of order`)
    }
    // (c) everything resolves: after enough clock advance nothing stays pending
    state.t += 1e9
    pump.run(1000)
    assert.equal(queue.pending().length, 0, `seed ${seed}: queue did not drain`)
    // (d) every message emitted exactly once; failed ⊆ delivered; failures reported
    assert.deepEqual([...new Set(sink.deliveredIds())].sort(), enqueueOrder.map((x) => x).sort(), `seed ${seed}: delivery set mismatch`)
    for (const id of sink.failedIds()) assert.ok(sink.deliveredIds().includes(id), `seed ${seed}: failed without attempt`)
    assert.equal(retrier.delayFor(1), 100)
  }
}

